function useLocalState<T,>(key: string, initial: T): [T, Dispatch<SetStateAction<T>>] {
  const [value, setValue] = useState<T>(() => {
    try {
      const data = localStorage.getItem(key);
      if (!data) return initial;
      const parsed: unknown = JSON.parse(data);
      if (Array.isArray(initial)) return (Array.isArray(parsed) ? parsed : initial) as T;
      if (typeof initial === 'string') return (typeof parsed === 'string' ? parsed : initial) as T;
      if (typeof initial === 'number') return (typeof parsed === 'number' && Number.isFinite(parsed) ? parsed : initial) as T;
      if (typeof initial === 'boolean') return (typeof parsed === 'boolean' ? parsed : initial) as T;
      if (initial && typeof initial === 'object') {
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return initial;
        if (key === 'cs-star-filters-v2') {
          const filter = parsed as Partial<Filters>;
          return { ...initial, ...filter, priceTiers: Array.isArray(filter.priceTiers) ? filter.priceTiers : [] } as T;
        }
        if (key === 'cs-star-profile') {
          const profile = parsed as Record<string, unknown>;
          return { name: typeof profile.name === 'string' ? profile.name : 'Campus foodie', faculty: typeof profile.faculty === 'string' ? profile.faculty : '' } as T;
        }
        return parsed as T;
      }
      return initial;
    } catch { return initial; }
  });
  useEffect(() => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { window.dispatchEvent(new Event('cs-storage-error')); } }, [key, value]);
  return [value, setValue];
}
