type HomePreferences = { budget: 0 | 1 | 2 | 3; interests: string[] };

function WelcomeDialog({ facultyId, preferences, onComplete }: { facultyId: string; preferences: HomePreferences; onComplete: (faculty: string, preferences: HomePreferences) => void }) {
  const { t, lang } = useI18n();
  const [faculty, setFaculty] = useState(facultyId);
  const [budget, setBudget] = useState<HomePreferences['budget']>(preferences.budget);
  const [interests, setInterests] = useState<string[]>(preferences.interests);
  const options = [
    { id: 'coffee', icon: Coffee, label: t('Coffee & study breaks', 'قهوة وبريك مذاكرة') },
    { id: 'quick', icon: UtensilsCrossed, label: t('Quick meals', 'وجبات سريعة') },
    { id: 'sweet', icon: Sparkles, label: t('Sweet treats', 'حلويات') },
  ];
  const finish = () => onComplete(faculty, { budget, interests });
  return <Dialog title={t('Make CS Family Star yours', 'خلّي CS Family Star على مزاجك')} onClose={finish} className="welcome-dialog"><div className="dialog-body">
    <div className="welcome-heading"><span><Sparkles size={26} /></span><div><p className="eyebrow">{t('A FOOD GUIDE FOR FUE', 'دليل أكل لجامعة المستقبل')}</p><h3>{t('Start with your campus routine.', 'ابدأ بروتينك في الجامعة.')}</h3><p>{t('We’ll use this on your device to make nearby picks more useful.', 'هنستخدم المعلومات دي على جهازك علشان الترشيحات القريبة تكون أنسب ليك.')}</p></div></div>
    <label className="field-label">{t('Where do your lectures start?', 'محاضراتك بتبدأ منين؟')}<select data-autofocus value={faculty} onChange={event => setFaculty(event.target.value)}>{faculties.map(item => <option key={item.id} value={item.id}>{lang === 'ar' ? item.nameAr : item.shortName}</option>)}</select></label>
    <fieldset className="welcome-choice"><legend>{t('Your usual food budget', 'ميزانيتك المعتادة للأكل')}</legend><div>{([{ value: 0, label: t('Any budget', 'أي ميزانية') }, { value: 1, label: `40–100 ${t('EGP', 'ج.م')}` }, { value: 2, label: `120–250 ${t('EGP', 'ج.م')}` }, { value: 3, label: `300+ ${t('EGP', 'ج.م')}` }] as const).map(option => <button type="button" key={option.value} className={budget === option.value ? 'active' : ''} onClick={() => setBudget(option.value)} aria-pressed={budget === option.value}>{option.label}</button>)}</div></fieldset>
    <fieldset className="welcome-choice"><legend>{t('What brings you here most?', 'إيه أكتر حاجة بتدور عليها؟')}</legend><div className="welcome-interest-list">{options.map(option => { const selected = interests.includes(option.id); return <button type="button" key={option.id} className={selected ? 'active' : ''} onClick={() => setInterests(current => selected ? current.filter(item => item !== option.id) : [...current, option.id])} aria-pressed={selected}><option.icon size={16} />{option.label}</button>; })}</div></fieldset>
    <p className="privacy-note"><Bookmark size={14} />{t('No account or location permission needed. You can change this anytime.', 'مش محتاج حساب أو إذن موقع. تقدر تغير ده في أي وقت.')}</p>
    <button className="button button-primary button-full" onClick={finish}>{t('Show my food guide', 'اعرض دليلي للأكل')}<ArrowRight size={16} /></button>
    <button className="text-button welcome-skip" onClick={() => onComplete(facultyId, { budget: 0, interests: [] })}>{t('Skip for now', 'تخطَّ الآن')}</button>
  </div></Dialog>;
}

